import{_ as t,o as e,c as o,a6 as c}from"./chunks/framework.BrkgobfX.js";const D=JSON.parse('{"title":"环境变量","description":"按用途分类的环境变量速查（认证、模型、网络、隐私、Bash 行为等）","frontmatter":{"title":"环境变量","description":"按用途分类的环境变量速查（认证、模型、网络、隐私、Bash 行为等）","source":"https://daiw.org/manual/claude-code/environment-variables"},"headers":[],"relativePath":"manual/agent/claude-code/environment-variables.md","filePath":"manual/agent/claude-code/environment-variables.md"}'),r={name:"manual/agent/claude-code/environment-variables.md"};function _(E,d,a,C,s,n){return e(),o("div",null,[...d[0]||(d[0]=[c(`<h1 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h1><blockquote><p>按用途分类的环境变量速查（认证、模型、网络、隐私、Bash 行为等）</p></blockquote><p>Claude Code 的绝大多数运行时行为都能用环境变量控制，且效果等价于在 <code>settings.json</code> 的 <code>env</code> 字段里写同名键值——写进 <code>settings.json</code> 的好处是不用改 shell 配置、且能提交到仓库让团队共享。</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;API_TIMEOUT_MS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1200000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;DISABLE_AUTOUPDATER&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>优先级</strong>：同一个行为如果既有环境变量又有 settings 字段，环境变量优先（例如 <code>ANTHROPIC_MODEL</code> 优先于 <code>model</code> 设置）。环境变量与 CLI 参数、<code>/</code> 命令的优先级则因功能而异，例如 <code>--model</code>/<code>/model</code> 优先于 <code>ANTHROPIC_MODEL</code>，而 <code>CLAUDE_CODE_EFFORT_LEVEL</code> 优先于 <code>/effort</code>。环境变量在<strong>启动时</strong>读取一次，运行中修改需要重启 <code>claude</code> 才生效。</p><p>⚠️ 写进 <code>env</code> 并不总是等价：项目级的 <code>.claude/settings.json</code> 与 <code>.claude/settings.local.json</code> 不能设置 <code>CLAUDE_CONFIG_DIR</code> 等目录变量（v2.1.251 起），也不能开启 OpenTelemetry 导出、设置导出端点或采集内容（v2.1.282 起，见下文 OpenTelemetry 一节）；少数安全相关的变量（如下文的 <code>CLAUDE_CODE_DISABLE_DANGEROUS_RM_TIMEOUT</code>）只认启动 Claude Code 时的环境，写在任何 settings 的 <code>env</code> 里都无效。</p><p>下面按用途分类列出常用变量；完整的长尾列表（约 250 个）见官方 <a href="https://code.claude.com/docs/en/env-vars" target="_blank" rel="noreferrer">Environment variables</a> 文档。</p><h2 id="认证与-api-路由" tabindex="-1">认证与 API 路由 <a class="header-anchor" href="#认证与-api-路由" aria-label="Permalink to &quot;认证与 API 路由&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>ANTHROPIC_API_KEY</code></td><td>直接用 API Key 鉴权，优先于已登录的订阅账号。非交互模式（<code>-p</code>）下始终生效；交互模式下首次使用会提示确认。<code>unset ANTHROPIC_API_KEY</code> 可临时切回订阅账号</td></tr><tr><td><code>ANTHROPIC_AUTH_TOKEN</code></td><td>自定义 <code>Authorization</code> 头的值（会自动加 <code>Bearer </code> 前缀）</td></tr><tr><td><code>ANTHROPIC_BASE_URL</code></td><td>把请求路由到自建代理/网关，而非 <code>api.anthropic.com</code></td></tr><tr><td><code>ANTHROPIC_CUSTOM_HEADERS</code></td><td>附加自定义请求头，格式 <code>Name: Value</code>，多个用换行分隔</td></tr><tr><td><code>ANTHROPIC_BETAS</code></td><td>逗号分隔的额外 <code>anthropic-beta</code> header，任何鉴权方式（含订阅）都生效</td></tr><tr><td><code>CLAUDE_CODE_USE_BEDROCK</code> / <code>CLAUDE_CODE_USE_VERTEX</code> / <code>CLAUDE_CODE_USE_FOUNDRY</code> / <code>CLAUDE_CODE_USE_ANTHROPIC_AWS</code></td><td>切换到 Amazon Bedrock / Google Cloud&#39;s Agent Platform / Microsoft Foundry / Claude Platform on AWS</td></tr><tr><td><code>CLAUDE_CODE_AUTO_MODE_SERVER</code></td><td>🆕 <strong>v2.1.273+</strong>：控制 auto mode 是否交给服务端分类器审查操作，<code>0</code> 改用 Claude Code 自己的分类器请求，<code>1</code> 启用服务端审查。v2.1.273 时 Bedrock、Vertex、Foundry 上暂时默认本地分类器；⚠️ v2.1.278 起 Claude API、Enterprise 以及 Bedrock、Vertex、Foundry 与网关上改为默认服务端分类器（分类器开销不再收费），v2.1.281 起直连 Anthropic API 时也认这个变量，v2.1.282 起关闭遥测的直连会话同样默认服务端。官方说明它是临时变量，以后可能移除</td></tr><tr><td><code>CLAUDE_CODE_AUTO_MODE_MODEL</code></td><td>🆕 <strong>v2.1.302+</strong>：指定客户端本地 auto mode 分类器使用的模型（不影响服务端 auto mode）</td></tr><tr><td><code>CLAUDE_CODE_ATTRIBUTION_HEADER</code></td><td>🆕 <strong>v2.1.299+</strong>：设为 <code>0</code> 移除经 Claude apps 网关（或 Claude Desktop Code 标签页 <code>code</code> 策略）运行的会话请求里的归属块</td></tr><tr><td><code>AWS_BEARER_TOKEN_BEDROCK</code></td><td>Amazon Bedrock 的 API Key 鉴权</td></tr><tr><td><code>CLAUDE_CODE_OAUTH_TOKEN</code></td><td>claude.ai 的 OAuth access token，适合 SDK/自动化环境，可用 <code>claude setup-token</code> 生成</td></tr><tr><td><code>CLAUDE_CODE_OAUTH_REFRESH_TOKEN</code> / <code>CLAUDE_CODE_OAUTH_SCOPES</code></td><td>用 refresh token 免浏览器完成登录，常用于容器/CI 预置认证</td></tr><tr><td><code>CLAUDE_CONFIG_DIR</code></td><td>覆盖配置目录（默认 <code>~/.claude</code>），便于多账号并存，如 <code>alias claude-work=&#39;CLAUDE_CONFIG_DIR=~/.claude-work claude&#39;</code>。⚠️ v2.1.251 起项目级 <code>.claude/settings.json</code> 的 <code>env</code> 不能再设置它（<code>CLAUDE_CODE_TMPDIR</code>、<code>TMPDIR</code> 同理），请写在 shell、用户级或托管设置里</td></tr><tr><td><code>VERTEX_REGION_CLAUDE_*</code></td><td>一组变量，分别覆盖各代 Claude 模型在 Google Cloud&#39;s Agent Platform 上的区域（如 <code>VERTEX_REGION_CLAUDE_5_SONNET</code>)；v2.1.280 起新增 Opus 5.5 对应的 <code>VERTEX_REGION_CLAUDE_5_5_OPUS</code></td></tr></tbody></table><h2 id="模型选择与推理" tabindex="-1">模型选择与推理 <a class="header-anchor" href="#模型选择与推理" aria-label="Permalink to &quot;模型选择与推理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>ANTHROPIC_MODEL</code></td><td>设置使用的模型，优先于 <code>model</code> 设置，但会被 <code>--model</code>/<code>/model</code> 覆盖</td></tr><tr><td><code>ANTHROPIC_DEFAULT_MODEL</code></td><td>🆕 <strong>v2.1.236+</strong>：设定新会话的起始模型。与 <code>ANTHROPIC_MODEL</code> 的区别在于，<code>/model</code> 选过的模型会覆盖它并跨重启保留</td></tr><tr><td><code>ANTHROPIC_DEFAULT_SONNET_MODEL</code> / <code>_OPUS_MODEL</code> / <code>_HAIKU_MODEL</code> / <code>_FABLE_MODEL</code></td><td>分别覆盖 <code>/model</code> 里 <code>sonnet</code>/<code>opus</code>/<code>haiku</code>/<code>fable</code> 别名对应的具体模型 ID，常用于网关/自定义路由场景</td></tr><tr><td><code>CLAUDE_CODE_SUBAGENT_MODEL</code></td><td>subagent 的默认模型。⚠️ v2.1.251 起它只是「默认值」：agent 定义里的 <code>model:</code> 与单次派生显式指定的模型优先于它</td></tr><tr><td><code>CLAUDE_CODE_SUBAGENT_MODEL_FORCE</code></td><td>🆕 <strong>v2.1.257+</strong>：把 <code>CLAUDE_CODE_SUBAGENT_MODEL</code>（未设则主模型）强制套到所有 subagent，无视 agent 定义与单次派生里的模型</td></tr><tr><td><code>CLAUDE_CODE_SUBAGENT_EFFORT</code></td><td>🆕 <strong>v2.1.316+</strong>：为未显式指定推理强度的 subagent 设置默认推理强度，不再继承主会话的强度</td></tr><tr><td><code>CLAUDE_CODE_WORKFLOW_SUBAGENT_MODEL</code></td><td>🆕 <strong>v2.1.296+</strong>：让所有动态工作流（workflow）agent 运行在指定模型上，其它 subagent 保持各自模型</td></tr><tr><td><code>CLAUDE_CODE_EFFORT_LEVEL</code></td><td>设置推理强度（<code>low</code>/<code>medium</code>/<code>high</code>/<code>xhigh</code>/<code>max</code>/<code>auto</code>），优先于 <code>/effort</code> 与 <code>effortLevel</code> 设置</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_ULTRATHINK</code></td><td>🆕 <strong>v2.1.316+</strong>：设为 <code>1</code> 关闭 <code>ultrathink</code> 关键词（v2.1.311 起交互终端里的 <code>ultrathink</code> 在 Opus 5.5、Sonnet 5.5、Haiku 5.5 与 Fable 5.1 上会把该轮推理强度提至 <code>xhigh</code>）</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_ADVISOR_TOOL</code></td><td>🆕 <strong>v2.1.300+</strong>：设为 <code>1</code> 关闭顾问工具（<code>/advisor</code>）</td></tr><tr><td><code>MAX_THINKING_TOKENS</code></td><td>扩展思考的 token 预算上限；设为 <code>0</code> 在 Anthropic API 上禁用思考（Fable 模型与 v2.1.280 起的 Opus 5.5 除外，它们无法关闭思考）</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_ADAPTIVE_THINKING</code></td><td>禁用 Opus 4.6 / Sonnet 4.6 的自适应推理，回退到固定思考预算（对 Fable 5、Sonnet 5、Opus 4.7+ 无效）</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_WEB_FETCH</code></td><td>🆕 <strong>v2.1.285+</strong>：设为 <code>1</code> 禁用内置 WebFetch 工具</td></tr><tr><td><code>CLAUDE_CODE_MAX_OUTPUT_TOKENS</code></td><td>单次请求的最大输出 token 数</td></tr><tr><td><code>CLAUDE_CODE_MAX_CONTEXT_TOKENS</code></td><td>覆盖 Claude Code 假定的上下文窗口大小，用于自定义模型路由场景</td></tr><tr><td><code>CLAUDE_CODE_AUTO_COMPACT_WINDOW</code> / <code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</code></td><td>自定义自动压缩触发的上下文容量阈值及百分比（⚠️ v2.1.304 起 <code>CLAUDE_CODE_AUTO_COMPACT_WINDOW</code> 支持 <code>k</code> 与 <code>M</code> 后缀，如 <code>200k</code>，超出范围时告警）</td></tr><tr><td><code>CLAUDE_CODE_IDLE_COMPACT_MIN_TOKENS</code></td><td>🆕 <strong>v2.1.299+</strong>：调整空闲自动压缩（Idle compaction，对话闲置约 54 分钟后在 1 小时缓存过期前自动压缩）触发的最小 token 阈值，默认 200K；要关闭空闲自动压缩请在 <code>settings.json</code> 设 <code>&quot;idleCompaction&quot;: false</code> 或在 <code>/config</code> 切换</td></tr><tr><td><code>DISABLE_AUTO_COMPACT</code></td><td>禁用自动压缩，保留手动 <code>/compact</code></td></tr><tr><td><code>DISABLE_COMPACT</code></td><td>连手动 <code>/compact</code> 一起禁用（⚠️ v2.1.311 起写在 settings 文件或 Mod <code>$.env.set</code> 里只能关闭压缩，不能重新开启）</td></tr><tr><td><code>CLAUDE_CODE_MODEL_CATALOG</code></td><td>🆕 <strong>v2.1.311+</strong>：设为 <code>off</code> 关闭 Bedrock、Mantle、Vertex 与 Foundry 从 <code>downloads.claude.ai</code> 加载签名模型目录配置</td></tr><tr><td><code>CLAUDE_CODE_SIMPLE_SYSTEM_PROMPT</code></td><td>🆕 <strong>v2.1.312+</strong>：Bedrock、Vertex、Foundry 与 Mantle 对未识别的模型名（如自定义部署名、推理配置 ARN）默认改用精简系统提示词；设为 <code>0</code> 保留完整系统提示词</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_REFUSAL_FALLBACK</code></td><td>🆕 <strong>v2.1.312+</strong>：设为 <code>1</code> 关闭消息被安全标记后的自动模型切换（v2.1.312 起该切换也覆盖未识别的模型名）</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_1M_CONTEXT</code></td><td>禁用 1M 上下文窗口支持，常用于有合规要求的企业环境。⚠️ v2.1.223 起适用范围从一份固定模型名单扩大到<strong>所有原生 1M 窗口的 Claude 模型</strong>，统一靠自动压缩压到 200K；压不住时启动会告警</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_UNKNOWN_MODEL_WINDOW_ENFORCEMENT</code></td><td>设为 <code>1</code> 恢复旧行为：不再把<strong>未识别的模型 ID</strong> 约束在假定的上下文窗口内（v2.1.223 起默认约束）</td></tr></tbody></table><h2 id="网络、代理与超时" tabindex="-1">网络、代理与超时 <a class="header-anchor" href="#网络、代理与超时" aria-label="Permalink to &quot;网络、代理与超时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>API_TIMEOUT_MS</code></td><td>单次 API 请求超时（默认 600000ms，即 10 分钟）</td></tr><tr><td><code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code> / <code>NO_PROXY</code></td><td>标准代理配置，<code>NO_PROXY</code> 支持逗号分隔的域名/IP 白名单</td></tr><tr><td><code>CLAUDE_CODE_CERT_STORE</code></td><td>TLS 信任的 CA 证书来源，<code>bundled</code>（内置 Mozilla CA 集）和/或 <code>system</code>，默认两者都用</td></tr><tr><td><code>CLAUDE_CODE_CLIENT_CERT</code> / <code>CLAUDE_CODE_CLIENT_KEY</code> / <code>CLAUDE_CODE_CLIENT_KEY_PASSPHRASE</code></td><td>mTLS 客户端证书鉴权</td></tr><tr><td><code>CLAUDE_ENABLE_STREAM_WATCHDOG</code> / <code>CLAUDE_STREAM_IDLE_TIMEOUT_MS</code></td><td>流式响应的空闲看门狗开关与超时时间，防止连接静默卡死</td></tr><tr><td><code>CLAUDE_CODE_PROXY_RESOLVES_HOSTS</code></td><td>允许代理而非本机做 DNS 解析</td></tr><tr><td><code>CLAUDE_CODE_GATEWAY_HINT_HEADERS</code></td><td>🆕 <strong>v2.1.273+</strong>：设为 <code>1</code> 后，发往 LLM 网关的请求附带 <code>x-claude-code-request-class</code>、<code>x-claude-code-agent-type</code>、<code>x-claude-code-prev-tool-durations</code>、<code>x-claude-code-compaction</code>、<code>x-claude-code-context-compacted</code> 等提示请求头；🆕 v2.1.283 起再加上 <code>x-claude-code-prompt-id</code>（同一条用户提示词触发的请求共用一个随机 UUID，含它派生的 subagent 轮次），网关可以据此按提示词分组</td></tr><tr><td><code>CLAUDE_GATEWAY_PROXY_IS_EGRESS_BOUNDARY</code></td><td>🆕 <strong>v2.1.277+</strong>：给唯一出口是正向代理的 Claude apps 网关用，设为 <code>1</code> 后每个出站请求都把主机名交给代理，不在本地解析</td></tr><tr><td><code>CLAUDE_GATEWAY_DRAIN_TIMEOUT_MS</code></td><td>🆕 <strong>v2.1.274+</strong>：Claude apps 网关收到 SIGTERM 后，让进行中的请求最多再跑多久才退出（更新日志的说法是“最多 25 秒”），不再一下切断所有流</td></tr><tr><td><code>CLAUDE_CODE_WEBFETCH_DEADLINE_MS</code></td><td>🆕 <strong>v2.1.268+</strong>：WebFetch 单次抓取的总时限（默认 300 秒，防止被一直不结束响应的服务器挂住）；设 <code>0</code> 关闭</td></tr><tr><td><code>CLAUDE_CODE_WEBFETCH_CACHE_TTL_MS</code></td><td>🆕 <strong>v2.1.233+</strong>：WebFetch 会话内 URL 缓存的有效期（默认 15 分钟）</td></tr><tr><td><code>CLAUDE_CODE_OVERLOADED_RETRY_BASE_DELAY_MS</code> / <code>CLAUDE_CODE_OVERLOADED_RETRY_MAX_DELAY_MS</code></td><td>🆕 <strong>v2.1.292+ / v2.1.296+</strong>：重试 529 过载请求时退避算法的基础延迟与最大延迟</td></tr><tr><td><code>CLAUDE_CODE_RETRY_WATCHDOG_MAX_WAIT_MS</code> / <code>_MAX_USAGE_LIMIT_WAIT_MS</code> / <code>_USAGE_LIMIT_RECHECK_MS</code></td><td>🆕 <strong>v2.1.295+ / v2.1.301+ / v2.1.305+</strong>：在无人值守重试模式（<code>CLAUDE_CODE_RETRY_WATCHDOG</code>）下，分别限制等待 429/529 的最长时间、额度重置时间过远时直接结束请求的最大等待时长，以及定期重查提前解除的用量上限的间隔</td></tr><tr><td><code>CLAUDE_CODE_GZIP_REQUEST_BODIES</code></td><td>🆕 <strong>v2.1.300+</strong>：发往 <code>api.anthropic.com</code> 的大请求即使关闭遥测也默认启用 gzip 压缩；设为 <code>0</code> 关闭</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_LOOPED_CROSS_CERT_DROP</code></td><td>🆕 <strong>v2.1.316+</strong>：保留系统证书库里互相交叉签名成环的证书（供私有 CA 依赖此类证书的服务器使用）</td></tr></tbody></table><h2 id="bash-工具行为" tabindex="-1">Bash 工具行为 <a class="header-anchor" href="#bash-工具行为" aria-label="Permalink to &quot;Bash 工具行为&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>BASH_DEFAULT_TIMEOUT_MS</code></td><td>长时间运行命令的默认超时（默认 120000ms）</td></tr><tr><td><code>BASH_MAX_TIMEOUT_MS</code></td><td>模型可为单条命令设置的超时上限（默认 600000ms）</td></tr><tr><td><code>BASH_MAX_OUTPUT_LENGTH</code></td><td>输出超过该字符数时落盘保存，Claude 只拿到文件路径 + 预览（v2.1.261 起也可用 <code>bashOutputMaxChars</code> 设置调高，最高 128K 字符）</td></tr><tr><td><code>CLAUDE_CODE_SHELL</code></td><td>指定 Bash 工具使用的 shell 路径（仅支持 <code>bash</code>/<code>zsh</code>)</td></tr><tr><td><code>CLAUDE_CODE_SHELL_PREFIX</code></td><td>给所有 Claude Code 派生的 shell 命令套一层前缀命令，常用于审计/日志</td></tr><tr><td><code>CLAUDE_BASH_MAINTAIN_PROJECT_WORKING_DIR</code></td><td>每条 Bash/PowerShell 命令执行后都恢复到最初的工作目录</td></tr><tr><td><code>CLAUDE_CODE_USE_POWERSHELL_TOOL</code></td><td>Windows/Linux/macOS 上启用 PowerShell 工具（需要 <code>pwsh</code> 在 PATH 上）</td></tr><tr><td><code>CLAUDE_CODE_GIT_BASH_PATH</code></td><td>Windows 下手动指定 Git Bash 路径</td></tr><tr><td><code>CLAUDE_CODE_TOOL_MEMORY_LIMIT</code></td><td>🆕 <strong>v2.1.233+</strong>（Linux）：用内存 cgroup 限制 Bash 工具命令，防止失控的构建拖垮整个会话</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_DANGEROUS_RM_TIMEOUT</code></td><td>🆕 <strong>v2.1.281+</strong>：v2.1.281 起 auto mode 与 <code>--dangerously-skip-permissions</code> 下，危险删除（关键路径上的 <code>rm</code> 等）的确认最多等 2 分钟，无人回答就拒绝并附上改写提示；设为 <code>1</code> 取消这个时限（auto mode 改交分类器裁决，bypass 模式则一直等你回答）。只认启动 Claude Code 时的环境，写在 settings 的 <code>env</code> 里无效</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_SUBSTITUTION_RM_PROMPT</code></td><td>🆕 <strong>v2.1.281+</strong>：v2.1.281 起目标完全来自命令替换的递归 <code>rm</code>（如 <code>rm -rf &quot;$(pwd)&quot;</code>）即使有 Bash allow 规则也会询问；设为 <code>1</code> 关闭这项检查（其它关键路径检查照常）。同样只认启动环境</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_POWERSHELL_CMD_RM_DENY</code></td><td>🆕 <strong>v2.1.283+</strong>（Windows）：v2.1.283 起 PowerShell 工具拒绝经 <code>cmd</code> 用 <code>rd</code>、<code>rmdir</code>、<code>del</code>、<code>erase</code> 删除驱动器根目录、主目录等系统路径；设为 <code>1</code> 关闭这项检查。同样只认启动环境（这个变量见于官方文档，更新日志只记了这项修复）</td></tr><tr><td><code>CLAUDE_CODE_STRICT_INLINE_SHELL_RM_PROMPT</code></td><td>🆕 <strong>v2.1.299+</strong>：v2.1.299 起不再对不含 <code>rm</code> 的 <code>sh -c</code> 脚本误弹确认；若脚本在运行时动态拼出 Claude Code 静态读不到的 <code>rm</code>，设为 <code>1</code> 仍强制弹出确认</td></tr></tbody></table><h2 id="更新、遥测与隐私" tabindex="-1">更新、遥测与隐私 <a class="header-anchor" href="#更新、遥测与隐私" aria-label="Permalink to &quot;更新、遥测与隐私&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>DISABLE_AUTOUPDATER</code></td><td>关闭后台自动更新检查，<code>claude update</code> 仍可手动更新</td></tr><tr><td><code>DISABLE_UPDATES</code></td><td>连手动更新一起彻底禁止，适合自建分发渠道</td></tr><tr><td><code>CLAUDE_CODE_PACKAGE_MANAGER_AUTO_UPDATE</code></td><td>让 Homebrew/WinGet 安装也能在后台自动跑升级命令</td></tr><tr><td><code>DISABLE_TELEMETRY</code> / <code>DO_NOT_TRACK</code></td><td>退出遥测收集（不含代码、文件路径、bash 命令等用户数据），两者等价。⚠️ 关闭遥测的会话不拉取 feature flag，一些默认值随之不同：v2.1.282 起直连 Anthropic API 时 auto mode 默认用服务端分类器，v2.1.283 起没配置权限模式的交互式会话以 auto mode 起步；v2.1.283 修复了关闭遥测时付费套餐用不了 Remote Control</td></tr><tr><td><code>DISABLE_ERROR_REPORTING</code></td><td>退出 Sentry 错误上报</td></tr><tr><td><code>DISABLE_GROWTHBOOK</code></td><td>禁用 feature flag 拉取，统一使用代码内置默认值</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC</code></td><td>一次性等价于同时设置 <code>DISABLE_AUTOUPDATER</code> + <code>DISABLE_FEEDBACK_COMMAND</code> + <code>DISABLE_ERROR_REPORTING</code> + <code>DISABLE_TELEMETRY</code>，适合内网/隔离环境</td></tr><tr><td><code>DISABLE_COST_WARNINGS</code></td><td>关闭费用提醒</td></tr><tr><td><code>DISABLE_INSTALLATION_CHECKS</code></td><td>关闭安装方式警告（仅在你手动管理安装路径时使用）</td></tr><tr><td><code>IS_DEMO</code></td><td>演示模式：隐藏邮箱/组织名，跳过 onboarding，适合直播/录屏</td></tr></tbody></table><h2 id="会话、上下文与运行时" tabindex="-1">会话、上下文与运行时 <a class="header-anchor" href="#会话、上下文与运行时" aria-label="Permalink to &quot;会话、上下文与运行时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CLAUDE_CODE_DISABLE_AUTO_MEMORY</code></td><td>禁用/强制开启自动记忆（<code>1</code> 禁用，<code>0</code> 强制开启）</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_CLAUDE_MDS</code></td><td>不加载任何 CLAUDE.md 记忆文件</td></tr><tr><td><code>CLAUDE_CODE_MAX_TURNS</code></td><td>未显式传 <code>--max-turns</code> 时的默认轮数上限</td></tr><tr><td><code>CLAUDE_CODE_MAX_TOOL_USE_CONCURRENCY</code></td><td>只读工具与 subagent 的最大并行数（默认 10）</td></tr><tr><td><code>CLAUDE_CODE_ENABLE_TASKS</code></td><td>控制是否使用结构化 Task 工具而非旧版 <code>TodoWrite</code>（2.1.142 起默认开启）</td></tr><tr><td><code>CLAUDE_CODE_ENABLE_TODO_TOOLS</code></td><td>⚠️ v2.1.268 起任务追踪工具（Task 系列与 <code>TodoWrite</code>）只在 Claude 3.x、Opus 4.0–4.7、Sonnet 4.0–4.6、Haiku 4.5 上提供；设为 <code>1</code> 在其它（更新的）模型上找回</td></tr><tr><td><code>CLAUDE_CODE_RESTRICTED</code></td><td>🆕 <strong>v2.1.248+</strong>：等价于 <code>--restricted</code>，移除能执行命令或代码的内置工具与 <code>WebFetch</code>，文件工具限定在工作目录内，拒绝 <code>bypassPermissions</code>，并忽略用户、项目、本机 settings 文件</td></tr><tr><td><code>CLAUDE_CODE_GOAL_CHECKIN_MINUTES</code></td><td>v2.1.234+：<code>/goal</code> 被后台任务卡住等待时，多久主动检查一次进度（默认 30 分钟，之后退避）；设 <code>0</code> 关闭</td></tr><tr><td><code>CLAUDE_CODE_SKIP_PROMPT_HISTORY</code></td><td>不写会话记录到磁盘，无法被 <code>--resume</code>/<code>--continue</code> 找到，适合一次性脚本化会话</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_FILE_CHECKPOINTING</code></td><td>禁用文件检查点，<code>/rewind</code> 将无法回滚代码改动</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_GIT_INSTRUCTIONS</code></td><td>从系统提示词里移除内置的 commit/PR 工作流指引</td></tr><tr><td><code>CLAUDECODE</code></td><td>Claude Code 派生的子进程里会被设为 <code>1</code>，用于脚本判断“我是不是被 Claude Code 调用的”</td></tr><tr><td><code>CLAUDE_CODE_CHILD_SESSION</code></td><td>类似 <code>CLAUDECODE</code>，但只有 Claude Code 自己派生子进程时才设置，可用来区分嵌套会话</td></tr><tr><td><code>CLAUDE_CODE_SESSION_ID</code></td><td>子进程/hook 里的当前会话 ID，用于日志关联</td></tr><tr><td><code>CLAUDE_CODE_RESUME_INTERRUPTED_TURN</code></td><td>是否在恢复会话时自动重跑被中断的那一轮；设为 <code>0</code> 关闭（v2.1.221 起假值才被正确识别）</td></tr><tr><td><code>CLAUDE_CODE_SIMPLE</code></td><td>精简系统提示词 + 仅 Bash/文件读写工具，等价于 <code>--bare</code></td></tr><tr><td><code>CLAUDE_ENV_FILE</code></td><td>一个 shell 脚本路径，每条 Bash 命令执行前会先 source 它，用于跨命令保持 virtualenv/conda 的激活状态</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_FILE_MENTIONS</code></td><td>🆕 <strong>v2.1.299+</strong>：设为 <code>1</code> 后，<code>@</code> 文件引用只把文件路径传给 Claude 由文件工具按需读取，不再直接内联文件内容</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_ULTRAREVIEW_TRUST_CHECK</code></td><td>🆕 <strong>v2.1.309+</strong>：设为 <code>1</code> 跳过 <code>claude ultrareview</code> 运行前的目录信任确认（等价于传 <code>--trust-workspace</code>）</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_NESTED_SESSION_ID</code></td><td>🆕 <strong>v2.1.317+</strong>：在自托管运行环境上设为 <code>1</code>，让会话内运行的 <code>claude -p</code> 沿用外层会话 ID 与 transcript（v2.1.317 起默认改为独立 ID 以免串台）</td></tr></tbody></table><h2 id="后台任务与并行" tabindex="-1">后台任务与并行 <a class="header-anchor" href="#后台任务与并行" aria-label="Permalink to &quot;后台任务与并行&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CLAUDE_CODE_DISABLE_BACKGROUND_TASKS</code></td><td>禁用全部后台任务能力（<code>run_in_background</code>、自动转后台、<code>Ctrl+B</code>)</td></tr><tr><td><code>CLAUDE_AUTO_BACKGROUND_TASKS</code></td><td>强制开启长任务自动转后台（约运行 2 分钟后）</td></tr><tr><td><code>CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS</code></td><td>同时在跑的 subagent 数量上限（默认 20，v2.1.217 引入），防止一条消息无限扇出后台 agent</td></tr><tr><td><code>CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH</code></td><td>subagent 嵌套派生的深度上限（v2.1.219 起默认 3；设为 <code>1</code> 即关闭嵌套）</td></tr><tr><td><code>CLAUDE_CODE_WORKFLOW_MAX_CONCURRENT_AGENTS</code></td><td>🆕 <strong>v2.1.269+</strong>：Workflow 工具单次运行的并发 agent 上限（1–256），推理密集的大扇出可调高</td></tr><tr><td><code>CLAUDE_ASYNC_AGENT_STALL_TIMEOUT_MS</code></td><td>后台 subagent 的停滞超时（默认 10 分钟无进展则判定失败）</td></tr><tr><td><code>TASK_MAX_OUTPUT_LENGTH</code></td><td>subagent 输出截断前的最大字符数（默认 32000）。⚠️ v2.1.277 起 TaskOutput 工具被移除（Claude 改用 Read 读取后台任务的输出文件），该变量不再有任何作用</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_AGENT_VIEW</code></td><td>关闭 <code>claude agents</code>/<code>--bg</code>/<code>/background</code> 等后台 agent 能力</td></tr><tr><td><code>CLAUDE_CODE_TASK_LIST_ID</code></td><td>多个 Claude Code 实例共享同一个任务列表</td></tr><tr><td><code>CLAUDE_CODE_FORK_SUBAGENT</code></td><td>🆕 <strong>v2.1.302+</strong>：v2.1.302 起 fork 型 subagent（<code>subagent_type: &quot;fork&quot;</code>）在 <code>claude -p</code>、Agent SDK、桌面端与 VS Code 中也默认开启（与终端一致）；设为 <code>0</code> 关闭</td></tr></tbody></table><h2 id="mcp-相关" tabindex="-1">MCP 相关 <a class="header-anchor" href="#mcp-相关" aria-label="Permalink to &quot;MCP 相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>MCP_TIMEOUT</code></td><td>MCP 服务器启动超时（默认 30000ms）</td></tr><tr><td><code>MCP_TOOL_TIMEOUT</code></td><td>单次 MCP 工具调用超时（默认约 28 小时，几乎不设限）</td></tr><tr><td><code>MCP_CONNECTION_NONBLOCKING</code></td><td>设为 <code>0</code> 恢复旧版“启动时阻塞等待 MCP 连接”行为（2.1.142 起默认非阻塞）；v2.1.281 修复了设为 <code>0</code> 时 claude.ai connector 1 秒就放弃、不遵守 <code>MCP_CONNECT_TIMEOUT_MS</code></td></tr><tr><td><code>MCP_CONNECT_TIMEOUT_MS</code></td><td>阻塞模式下等待 MCP 连接批次完成的超时（默认 5000ms）</td></tr><tr><td><code>CLAUDE_CODE_MCP_STARTUP_WAIT_MS</code></td><td>🆕 <strong>v2.1.274+</strong>：非交互模式下，首轮最多等多久让正在连接的 MCP 服务器连上（<code>0</code> = 不等）</td></tr><tr><td><code>MCP_SDK_GENERATION</code> / <code>MCP_PROTOCOL_NEGOTIATION</code></td><td>⚠️ v2.1.274 起 Bedrock、Vertex、Foundry 与关闭遥测的安装，对直连 HTTP 的 MCP 服务器也默认使用 v2 MCP 客户端与 MCP <code>2026-07-28</code> 协议协商；v2.1.292 起本地（stdio）MCP 服务器在所有安装上同样默认协商 <code>2026-07-28</code> 协议，v2.1.295 / v2.1.299 起 claude.ai、云端与 Remote Control connector 也一致；设 <code>MCP_SDK_GENERATION=v1</code> 或 <code>MCP_PROTOCOL_NEGOTIATION=legacy</code> 退出</td></tr><tr><td><code>MCP_SERVER_CONNECTION_BATCH_SIZE</code> / <code>MCP_REMOTE_SERVER_CONNECTION_BATCH_SIZE</code></td><td>本地（stdio）/远程（HTTP、SSE）MCP 服务器启动时的并行连接数</td></tr><tr><td><code>MAX_MCP_OUTPUT_TOKENS</code></td><td>MCP 工具响应允许的最大 token 数（默认 25000）</td></tr><tr><td><code>CLAUDE_CODE_MAX_MCP_DESCRIPTION_LENGTH</code></td><td>🆕 <strong>v2.1.280+</strong>：发给模型的每个 MCP 工具描述与每个服务器说明的字符上限（⚠️ v2.1.296 起预发送描述与服务器说明默认上限从 2048 提高到 4096，超出部分截断；v2.1.295 起经 tool search 按需加载的工具描述截断上限提高到 16384；v2.1.299 起 <code>api.anthropic.com</code> 上的第一方 MCP 服务器不截断）</td></tr><tr><td><code>CLAUDE_CODE_MCP_ALLOWLIST_ENV</code></td><td>只给 stdio MCP 服务器传递安全基线环境变量，而不是继承整个 shell 环境</td></tr><tr><td><code>CLAUDE_CODE_MCP_TOOL_IDLE_TIMEOUT</code></td><td>远程 MCP 工具调用的空闲超时（默认 5 分钟，超时则报错而非无限等待）</td></tr><tr><td><code>ENABLE_TOOL_SEARCH</code></td><td>控制 MCP 工具是否延迟加载（按需检索）还是一次性全部载入上下文</td></tr></tbody></table><h2 id="插件与技能" tabindex="-1">插件与技能 <a class="header-anchor" href="#插件与技能" aria-label="Permalink to &quot;插件与技能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CLAUDE_CODE_PLUGIN_CACHE_DIR</code></td><td>覆盖插件根目录（默认 <code>~/.claude/plugins</code>)</td></tr><tr><td><code>CLAUDE_CODE_PLUGIN_DIRS</code></td><td>🆕 <strong>v2.1.280+</strong>：本次会话要加载的插件目录，每个都像 <code>--plugin-dir</code> 那样加载；Unix 用 <code>:</code>、Windows 用 <code>;</code> 分隔，路径须为绝对路径或以 <code>~</code> 开头（相对路径会被跳过）。这个变量见于官方文档，更新日志里没有单列</td></tr><tr><td><code>CLAUDE_CODE_PLUGIN_GIT_TIMEOUT_MS</code></td><td>安装/更新插件时 git 操作的超时（默认 120000ms）</td></tr><tr><td><code>CLAUDE_CODE_PLUGIN_PREFER_HTTPS</code></td><td>插件仓库用 HTTPS 而非 SSH 克隆，适合没配 SSH key 的 CI/容器环境</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_BUNDLED_SKILLS</code></td><td>禁用随 Claude Code 自带的技能与工作流（不影响自定义/插件技能）</td></tr><tr><td><code>CLAUDE_CODE_SYNC_SKILLS</code></td><td>非交互模式下，首次查询前把你在 claude.ai 上启用的技能同步到本地。🆕 v2.1.275 起用 claude.ai 账号登录的终端会话会同步该账号上启用的技能与插件，要关闭请把设置 <code>syncClaudeAiSkills</code> / <code>syncClaudeAiPlugins</code> 设为 <code>false</code>（见<a href="/Front2Full/manual/agent/claude-code/configuration-files">配置文件</a>）</td></tr><tr><td><code>SLASH_COMMAND_TOOL_CHAR_BUDGET</code></td><td>技能元数据展示给 Skill 工具时的字符预算，技能很多时可调大避免描述被裁剪</td></tr></tbody></table><h2 id="终端-ui-与可访问性" tabindex="-1">终端 UI 与可访问性 <a class="header-anchor" href="#终端-ui-与可访问性" aria-label="Permalink to &quot;终端 UI 与可访问性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CLAUDE_CODE_ACCESSIBILITY</code></td><td>保持原生终端光标可见，便于屏幕放大镜类工具跟踪光标</td></tr><tr><td><code>CLAUDE_AX_SCREEN_READER</code></td><td>输出无装饰边框/动画的纯文本，适配屏幕阅读器（⚠️ v2.1.305 / v2.1.307 起写在 settings <code>env</code> 里时，以及 <code>axScreenReader</code> 设置，只在用户级、托管设置或 <code>--settings</code> 中生效）</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_MOUSE</code> / <code>CLAUDE_CODE_DISABLE_MOUSE_CLICKS</code></td><td>全屏渲染下禁用鼠标追踪 / 只禁用点击拖拽（保留滚轮）</td></tr><tr><td><code>CLAUDE_CODE_DISABLE_ALTERNATE_SCREEN</code></td><td>禁用全屏渲染，回退到传统主屏渲染器（终端原生回滚缓冲区可用）</td></tr><tr><td><code>CLAUDE_CODE_NO_FLICKER</code></td><td>启用全屏渲染（减少闪烁、长会话内存更平稳的实验性渲染器）</td></tr><tr><td><code>CLAUDE_CODE_TMUX_TRUECOLOR</code></td><td>允许 tmux 内使用 24 位真彩色（需先在 <code>~/.tmux.conf</code> 开启 <code>Tc</code>)</td></tr><tr><td><code>CLAUDE_CODE_SCROLL_SPEED</code></td><td>全屏渲染下的鼠标滚轮倍率</td></tr><tr><td><code>CLAUDE_CODE_HIDE_CWD</code></td><td>启动 Logo 里隐藏工作目录路径，适合截图/录屏</td></tr><tr><td><code>CLAUDE_CODE_SYNTAX_HIGHLIGHT</code></td><td>设为 <code>false</code> 关闭 diff 输出的语法高亮</td></tr><tr><td><code>FORCE_HYPERLINK</code></td><td>v2.1.217 起页脚 PR 徽标即使在检测不到终端超链接支持时（ssh/tmux 等）也渲染成可点链接；设为 <code>0</code>、<code>false</code>、<code>no</code> 或 <code>off</code> 退出（后三者自 v2.1.314 起生效）</td></tr></tbody></table><h2 id="opentelemetry-监控" tabindex="-1">OpenTelemetry 监控 <a class="header-anchor" href="#opentelemetry-监控" aria-label="Permalink to &quot;OpenTelemetry 监控&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>CLAUDE_CODE_ENABLE_TELEMETRY</code></td><td>启用 OpenTelemetry 数据采集，是配置其它 OTel 变量的前提。⚠️ v2.1.282 起，它以及选择导出器、设置导出端点（<code>OTEL_EXPORTER_OTLP_*_ENDPOINT</code> 等）、采集内容（<code>OTEL_LOG_*</code>）的变量写在项目级 <code>.claude/settings.json</code> / <code>.claude/settings.local.json</code> 的 <code>env</code> 里会被忽略（只有 <code>none</code>、<code>0</code> 这类关闭用的值仍然生效），要写在 shell、用户级或托管设置里；本地交互式会话启动时会提示，<code>/status</code> 与 <code>claude doctor</code> 会列出被忽略的变量，而 <code>-p</code> 与 Agent SDK 会话没有提示，升级后记得确认采集端还收得到数据</td></tr><tr><td><code>OTEL_LOG_USER_PROMPTS</code> / <code>OTEL_LOG_ASSISTANT_RESPONSES</code></td><td>是否在日志事件中包含用户提示词/模型回复原文（默认脱敏）</td></tr><tr><td><code>OTEL_LOG_TOOL_CONTENT</code> / <code>OTEL_LOG_TOOL_DETAILS</code></td><td>是否包含工具调用的输入输出内容与详细参数（默认关闭以保护敏感信息）。⚠️ v2.1.273 起 <code>OTEL_LOG_TOOL_DETAILS=1</code> 时，成本与 token 指标也带上真实的 agent、技能、插件与 MCP 服务器名；v2.1.283 起 <code>OTEL_LOG_TOOL_CONTENT=1</code> 时，MCP 工具、WebFetch 与 WebSearch 的输出也写进 <code>claude_code.tool</code> span 的 <code>tool.output</code> 事件</td></tr><tr><td><code>OTEL_METRICS_INCLUDE_SESSION_ID</code> / <code>_ACCOUNT_UUID</code> / <code>_VERSION</code></td><td>控制指标里包含哪些附加维度</td></tr><tr><td><code>OTEL_METRICS_INCLUDE_REPOSITORY</code></td><td>🆕 <strong>v2.1.269+</strong>：给 OTel 指标与事件打上 <code>vcs.*</code> 仓库属性；配合 <code>OTEL_LOG_TOOL_DETAILS</code> 时提交事件还带 <code>vcs.ref.head.*</code></td></tr><tr><td><code>OTEL_LOG_MANAGED_SETTINGS</code></td><td>🆕 <strong>v2.1.274+</strong>：同版本新增的 <code>claude_code.managed_settings_resolved</code> 事件记录托管设置的来源与策略 helper 状态；设为 <code>1</code> 时再附上脱敏后的设置与摘要</td></tr><tr><td><code>OTEL_LOG_RAW_API_BODIES</code></td><td>把完整的 API 请求与响应体作为 OTel 日志事件输出，供调试（v2.1.111+）。v2.1.274 起用 <code>file:&lt;dir&gt;</code> 形式时多一个 <code>index.jsonl</code>，事件新增 <code>request_body_id</code> / <code>message.id</code> 属性，能把每个响应对应到它的请求文件与 transcript 消息</td></tr><tr><td><code>CLAUDE_CODE_OTEL_CONTENT_MAX_LENGTH</code></td><td>调整 OTel 内容属性默认 60 KB 的截断上限（v2.1.214+）。同版本日志事件新增 <code>message.uuid</code>、<code>client_request_id</code>、<code>tool_source</code> 属性，便于消息级关联与工具来源追溯</td></tr><tr><td>标准 OTel 变量</td><td><code>OTEL_METRICS_EXPORTER</code>、<code>OTEL_LOGS_EXPORTER</code>、<code>OTEL_EXPORTER_OTLP_ENDPOINT</code>、<code>OTEL_EXPORTER_OTLP_PROTOCOL</code>、<code>OTEL_EXPORTER_OTLP_HEADERS</code>、<code>OTEL_RESOURCE_ATTRIBUTES</code> 等标准导出器配置同样支持</td></tr></tbody></table><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>DEBUG</code></td><td>设为 <code>1</code>/<code>true</code>/<code>yes</code>/<code>on</code> 开启调试模式，等价于 <code>--debug</code></td></tr><tr><td><code>CLAUDE_CODE_DEBUG_LOGS_DIR</code></td><td>调试日志文件路径（默认 <code>~/.claude/debug/&lt;timestamp&gt;.txt</code>)</td></tr><tr><td><code>CLAUDE_CODE_DEBUG_LOG_LEVEL</code></td><td>日志级别：<code>verbose</code>/<code>debug</code>（默认）/<code>info</code>/<code>warn</code>/<code>error</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>以上覆盖了日常最常用的变量类别。企业级场景（网关鉴权、Perforce 集成、屏幕阅读器细节、agent team 相关变量等）数量繁多且更新频繁，建议直接查阅官方 <a href="https://code.claude.com/docs/en/env-vars" target="_blank" rel="noreferrer">Environment variables</a> 页面获取权威、实时的完整列表。</p></div>`,32)])])}const A=t(r,[["render",_]]);export{D as __pageData,A as default};
